var taken = new List<string> { "9am" };
Cj.Eq(Solution.Book(taken, "10am"), "10am", "free slot booked");
Cj.Eq(taken.Count, 2, "slot recorded");
try
{
    Solution.Book(taken, "9am");
    Cj.True(false, "must throw");
}
catch (Solution.BookingConflictException ex)
{
    Cj.Eq(ex.Slot, "9am", "Slot carries the conflicting slot");
}
bool t = false;
try { Solution.Book(taken, "  "); } catch (ArgumentException) { t = true; }
Cj.True(t, "blank slot rejected");

Cj.Eq(Solution.Guard(() => 21, "answer"), 21, "result passes through");
bool t1 = false;
try { Solution.Guard<int>(() => throw new InvalidOperationException("boom"), "booking"); } catch (InvalidOperationException ex) { t1 = ex.Message.Contains("booking"); }
Cj.True(t1, "IOE wrapped with the label");
bool t2 = false;
try { Solution.Guard<int>(() => throw new ArgumentException("raw"), "booking"); } catch (ArgumentException) { t2 = true; }
Cj.True(t2, "other types propagate unchanged");
bool t3 = false;
try { Solution.Guard(() => 1, null); } catch (ArgumentException) { t3 = true; }
Cj.True(t3, "null label rejected");
